11	import WarningAmberIcon from '@mui/icons-material/WarningAmberOutlined';
12	import EventUpcomingIcon from '@mui/icons-material/EventAvailableOutlined';
13	import CheckCircleIcon from '@mui/icons-material/CheckCircleOutline';
14	import StatCard from '../../components/StatCard';
15	import StatusChip from '../../components/StatusChip';
16	import ConfirmDialog from '../../components/ConfirmDialog';
17	import ScheduleFormDialog from './ScheduleFormDialog';
18	import ScheduleDetailsModal from './ScheduleDetailsModal';
19	import * as scheduleApi from '../../api/scheduleApi';
20	import { SCHEDULE_STATUSES, NEXT_STATUS, isOverdue } from '../../utils/scheduleHelpers';
21	import { formatDate } from '../../utils/formatDate';
22	import { exportToCSV } from '../../utils/csvExport';
23	import { SCHEDULE_CSV_COLUMNS } from './scheduleCsvColumns';
24	import { SCHEDULE_STATUS_COLORS } from '../../theme/statusColors';
25	import { useAuth } from '../../context/AuthContext';
26	
27	const UPCOMING_WINDOW_DAYS = 7;
28	const RECENTLY_COMPLETED_LIMIT = 5;
29	
30	// Simple stat tiles rather than a full charting library — client feedback
31	// asked for "statistic/report" visibility, not a dedicated analytics page,
32	// so this stays lightweight and lives right where staff already work.
33	// Computed from the full (unfiltered) list, same as Lifts' stats endpoint
34	// is decoupled from its grid filters.
35	function computeStats(schedules) {
36	  const today = new Date();
37	  today.setHours(0, 0, 0, 0);
38	  const windowEnd = new Date(today);
39	  windowEnd.setDate(windowEnd.getDate() + UPCOMING_WINDOW_DAYS);
40	
41	  const upcoming = schedules.filter((schedule) => {
42	    if (schedule.status === 'Completed' || schedule.status === 'Cancelled') return false;
43	    const date = new Date(schedule.scheduledDate);
44	    return date >= today && date <= windowEnd;
45	  });
46	
47	  const overdue = schedules.filter(isOverdue);
48	
49	  const recentlyCompleted = schedules
50	    .filter((schedule) => schedule.status === 'Completed')
51	    .sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt))
52	    .slice(0, RECENTLY_COMPLETED_LIMIT);
53	
54	  return { upcomingCount: upcoming.length, overdueCount: overdue.length, recentlyCompletedCount: recentlyCompleted.length };
55	}
56	
57	export default function SchedulingPage() {
58	  const { user } = useAuth();
59	  const { enqueueSnackbar } = useSnackbar();
60	  const canEdit = user.role === 'Admin' || user.role === 'Manager';
61	
62	  const [schedules, setSchedules] = useState([]);
63	  const [loading, setLoading] = useState(true);
64	  const [search, setSearch] = useState('');
65	  const [statusFilter, setStatusFilter] = useState('');
66	  const [dateFilter, setDateFilter] = useState('');
67	
68	  const [formOpen, setFormOpen] = useState(false);
69	  const [editingSchedule, setEditingSchedule] = useState(null);
70	  const [deleteTarget, setDeleteTarget] = useState(null);
71	  const [viewingSchedule, setViewingSchedule] = useState(null);
72	
73	  const load = async () => {
74	    setLoading(true);
75	    try {
76	      const list = await scheduleApi.fetchSchedules();
77	      setSchedules(list);
78	    } catch {
79	      enqueueSnackbar('Failed to load schedules - is the backend running?', { variant: 'error' });
80	    } finally {
81	      setLoading(false);
82	    }
83	  };
84	
85	  useEffect(() => {
86	    load();
87	    // eslint-disable-next-line react-hooks/exhaustive-deps
88	  }, []);
89	
90	  const filteredSchedules = useMemo(() => {
91	    return schedules.filter((schedule) => {
92	      if (statusFilter && schedule.status !== statusFilter) return false;
93	      if (dateFilter && schedule.scheduledDate.slice(0, 10) !== dateFilter) return false;
94	      if (search) {
95	        const haystack = `${schedule.townCouncil} ${schedule.liftCompany} ${schedule.blockAddress} ${schedule.assignedInspector}`.toLowerCase();
96	        if (!haystack.includes(search.toLowerCase())) return false;
97	      }
98	      return true;
99	    });
100	  }, [schedules, search, statusFilter, dateFilter]);
101	
102	  const stats = useMemo(() => computeStats(schedules), [schedules]);
103	
104	  const handleSave = async (values) => {
105	    try {
106	      if (editingSchedule) {
107	        await scheduleApi.updateSchedule(editingSchedule._id, values);
108	        enqueueSnackbar('Schedule updated', { variant: 'success' });
109	      } else {
110	        await scheduleApi.createSchedule(values);
111	        enqueueSnackbar('Schedule created', { variant: 'success' });
112	      }
113	      setFormOpen(false);
114	      setEditingSchedule(null);
115	      load();
116	    } catch (err) {
117	      enqueueSnackbar(err.response?.data?.message || 'Failed to save schedule', { variant: 'error' });
118	    }
119	  };
120	
121	  const handleAdvanceStatus = async (schedule) => {
122	    const nextStatus = NEXT_STATUS[schedule.status];
123	    if (!nextStatus) return;
124	    try {
125	      await scheduleApi.updateSchedule(schedule._id, { status: nextStatus });
126	      enqueueSnackbar(`Marked ${schedule.blockAddress} as ${nextStatus}`, { variant: 'success' });
127	      load();
128	    } catch (err) {
129	      enqueueSnackbar(err.response?.data?.message || 'Failed to update status', { variant: 'error' });
130	    }
131	  };
132	
133	  const handleDelete = async () => {
134	    try {
135	      await scheduleApi.deleteSchedule(deleteTarget._id);
136	      enqueueSnackbar('Schedule cancelled', { variant: 'success' });
137	      setDeleteTarget(null);
138	      load();
139	    } catch (err) {
140	      enqueueSnackbar(err.response?.data?.message || 'Failed to cancel schedule', { variant: 'error' });
141	    }
142	  };
143	
144	  const handleExport = () => {
145	    exportToCSV('schedules.csv', filteredSchedules, SCHEDULE_CSV_COLUMNS);
146	  };
147	
148	  const columns = [
149	    {
150	      field: 'scheduledDate',
151	      headerName: 'Scheduled Date',
152	      width: 160,
153	      renderCell: (params) => (
154	        <Stack direction="row" spacing={0.5} alignItems="center">
155	          <span>{formatDate(params.value)}</span>
156	          {isOverdue(params.row) && (
157	            <Tooltip title="Past scheduled date, still open">
158	              <WarningAmberIcon fontSize="small" color="warning" />
159	            </Tooltip>
160	          )}
161	        </Stack>
162	      ),
163	    },
164	    { field: 'townCouncil', headerName: 'Town Council', width: 180 },
165	    { field: 'liftCompany', headerName: 'Lift Company', width: 160 },
166	    { field: 'blockAddress', headerName: 'Block/Lift Address', width: 200 },
167	    { field: 'assignedInspector', headerName: 'Inspector', width: 140 },
168	    {
169	      field: 'status',
170	      headerName: 'Status',
171	      width: 130,
172	      renderCell: (params) => <StatusChip value={params.value} colorMap={SCHEDULE_STATUS_COLORS} />,
173	    },
174	    {
175	      field: 'actions',
176	      headerName: 'Actions',
177	      width: canEdit ? 190 : 70,
178	      sortable: false,
179	      filterable: false,
180	      renderCell: (params) => (
181	        <Stack direction="row">
182	          <IconButton size="small" onClick={() => setViewingSchedule(params.row)} title="View details">
183	            <VisibilityIcon fontSize="small" />
184	          </IconButton>
185	          {canEdit && (
186	            <>
187	              {NEXT_STATUS[params.row.status] && (
188	                <Tooltip title={`Mark ${NEXT_STATUS[params.row.status]}`}>
189	                  <IconButton size="small" onClick={() => handleAdvanceStatus(params.row)}>
190	                    <ArrowForwardIcon fontSize="small" />
191	                  </IconButton>
