328	      </Box>
329	
330	      <Paper variant="outlined" sx={{ p: 3, mb: 3 }}>
331	        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: 1, mb: 2 }}>
332	          <Box>
333	            <Typography variant="h5" sx={{ fontWeight: 700 }}>{report.reportNo}</Typography>
