import { useMemo, useState } from 'react';
import { useSnackbar } from 'notistack';
import { Box, Button, Grid, IconButton, Stack, Typography } from '@mui/material';
import { DataGrid } from '@mui/x-data-grid';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/DeleteOutlined';
import BuildOutlinedIcon from '@mui/icons-material/BuildOutlined';
import DraftsOutlinedIcon from '@mui/icons-material/DraftsOutlined';
import PendingActionsOutlinedIcon from '@mui/icons-material/PendingActionsOutlined';
import VerifiedOutlinedIcon from '@mui/icons-material/VerifiedOutlined';
import StatCard from '../../components/StatCard';
import StatusChip from '../../components/StatusChip';
import ConfirmDialog from '../../components/ConfirmDialog';
import RectificationForm from './RectificationForm';
import RectificationDetail from './RectificationDetail';
import { useRectifications } from './useRectifications';
import { formatDate } from '../../utils/formatDate';
import { RECTIFICATION_STATUS_COLORS } from '../../theme/statusColors';
import { useAuth } from '../../context/AuthContext';

export default function RectificationsSection() {
  const { user } = useAuth();
  const { enqueueSnackbar } = useSnackbar();
  const canEdit = user.role === 'Admin' || user.role === 'Manager';

  const { rectifications, loading, create, update, endorse, remove } = useRectifications();

  const [formOpen, setFormOpen] = useState(false);
  const [editingRectification, setEditingRectification] = useState(null);
  const [viewingRectification, setViewingRectification] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);

  const stats = useMemo(
    () => ({
      total: rectifications.length,
      draft: rectifications.filter((r) => r.status === 'Draft').length,
      submitted: rectifications.filter((r) => r.status === 'Submitted').length,
      endorsed: rectifications.filter((r) => r.status === 'Endorsed').length,
    }),
    [rectifications]
  );

  const handleSave = async (values) => {
    try {
      if (editingRectification) {
        await update(editingRectification._id, values);
        enqueueSnackbar('Rectification updated', { variant: 'success' });
      } else {
        await create(values);
        enqueueSnackbar('Rectification created', { variant: 'success' });
      }
      setFormOpen(false);
      setEditingRectification(null);
    } catch (err) {
      enqueueSnackbar(err.response?.data?.message || 'Failed to save rectification', { variant: 'error' });
      throw err;
    }
  };

  const handleEndorse = async (id, endorsedBy) => {
    await endorse(id, endorsedBy);
    setViewingRectification(null);
  };

  const handleDelete = async () => {
    try {
      await remove(deleteTarget._id);
      enqueueSnackbar('Rectification deleted', { variant: 'success' });
      setDeleteTarget(null);
    } catch (err) {
      enqueueSnackbar(err.response?.data?.message || 'Failed to delete rectification', { variant: 'error' });
    }
  };

  const columns = [
    {
      field: 'photo',
      headerName: '',
      width: 56,
      sortable: false,
      filterable: false,
      renderCell: (params) =>
        params.row.proofPhotos?.[0] ? (
          <Box
            component="img"
            src={params.row.proofPhotos[0]}
            alt=""
            sx={{ width: 36, height: 36, objectFit: 'cover', borderRadius: 1, my: 'auto' }}
          />
        ) : null,
    },
    {
      field: 'defect',
      headerName: 'Defect',
      flex: 1,
      minWidth: 220,
      // Falls back to the defect's title when description is blank (often is) so the
      // column never renders looking empty for an otherwise perfectly good record.
      valueGetter: (_value, row) => row.defectId?.description || row.defectId?.title || '—',
    },
    {
      field: 'liftCompanyName',
      headerName: 'Lift Company',
      width: 180,
      valueGetter: (value) => value || '—',
    },
    {
      field: 'dateRectified',
      headerName: 'Date Rectified',
      width: 130,
      renderCell: (params) => formatDate(params.value),
    },
    {
      field: 'status',
      headerName: 'Status',
      width: 130,
      renderCell: (params) => <StatusChip value={params.value} colorMap={RECTIFICATION_STATUS_COLORS} />,
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: canEdit ? 60 : 20,
      sortable: false,
      filterable: false,
      renderCell: (params) =>
        canEdit && params.row.status === 'Draft' ? (
          <IconButton
            size="small"
            title="Delete rectification"
            onClick={(e) => {
              e.stopPropagation();
              setDeleteTarget(params.row);
            }}
          >
            <DeleteIcon fontSize="small" />
          </IconButton>
        ) : null,
    },
  ];

  return (
    <Box>
      <Stack direction="row" justifyContent="space-between" alignItems="flex-start" mb={3}>
        <Box>
          <Typography variant="h4">Rectifications</Typography>
          <Typography variant="body2" color="text.secondary">
            Track lift company fixes - proof photos, e-signature, and EM endorsement.
          </Typography>
        </Box>
        {canEdit && (
          <Button
            startIcon={<AddIcon />}
            variant="contained"
            onClick={() => {
              setEditingRectification(null);
              setFormOpen(true);
            }}
          >
            New Rectification
          </Button>
        )}
      </Stack>

      <Grid container spacing={2} mb={3}>
        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <StatCard label="Total" value={stats.total} icon={<BuildOutlinedIcon />} color="primary.main" />
        </Grid>
        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <StatCard label="Draft" value={stats.draft} icon={<DraftsOutlinedIcon />} color="text.secondary" />
        </Grid>
        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <StatCard label="Submitted" value={stats.submitted} icon={<PendingActionsOutlinedIcon />} color="info.main" />
        </Grid>
        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <StatCard label="Endorsed" value={stats.endorsed} icon={<VerifiedOutlinedIcon />} color="success.main" />
        </Grid>
      </Grid>

      <Box sx={{ height: 560, bgcolor: 'background.paper', borderRadius: 2, border: 1, borderColor: 'divider' }}>
        <DataGrid
          rows={rectifications}
          columns={columns}
          getRowId={(row) => row._id}
          loading={loading}
          disableRowSelectionOnClick
          onRowClick={(params) => setViewingRectification(params.row)}
          pageSizeOptions={[10, 25, 50]}
          initialState={{ pagination: { paginationModel: { pageSize: 10 } } }}
          sx={{ border: 'none', '& .MuiDataGrid-row': { cursor: 'pointer' } }}
          slots={{ noRowsOverlay: RectificationsEmptyState }}
        />
      </Box>

      <RectificationForm
        open={formOpen}
        rectification={editingRectification}
        onClose={() => {
          setFormOpen(false);
          setEditingRectification(null);
        }}
        onSubmit={handleSave}
      />

      <RectificationDetail
        open={Boolean(viewingRectification)}
        rectification={viewingRectification}
        onClose={() => setViewingRectification(null)}
        onEdit={() => {
          setEditingRectification(viewingRectification);
          setViewingRectification(null);
          setFormOpen(true);
        }}
        onEndorse={handleEndorse}
      />

      <ConfirmDialog
        open={Boolean(deleteTarget)}
        title="Delete Rectification"
        message="Delete this draft rectification? This cannot be undone."
        confirmLabel="Delete"
        confirmColor="error"
        onConfirm={handleDelete}
        onClose={() => setDeleteTarget(null)}
      />
    </Box>
  );
}

function RectificationsEmptyState() {
  return (
    <Stack alignItems="center" justifyContent="center" spacing={1} sx={{ height: '100%', color: 'text.secondary' }}>
      <BuildOutlinedIcon sx={{ fontSize: 32 }} />
      <Typography variant="body2">No rectifications yet.</Typography>
    </Stack>
  );
}

const mongoose = require('mongoose');

// Matches the client's paper spot-check form fields (Town Council / Lift Company /
// Block-Lift Address) so a schedule entry can stand alone even before the Lifts
// feature's own model/collection exists. Once Lifts is built, `liftId` can be
// populated to link back to the canonical lift record.
const STATUS_VALUES = ['Scheduled', 'Assigned', 'In Progress', 'Completed', 'Cancelled'];

const scheduleSchema = new mongoose.Schema(
  {
    townCouncil: { type: String, required: true, trim: true },
    liftCompany: { type: String, required: true, trim: true },
    blockAddress: { type: String, required: true, trim: true },

    // Optional forward link to the Lifts feature's model.
    liftId: { type: mongoose.Schema.Types.ObjectId, ref: 'Lift', default: null },

    scheduledDate: { type: Date, required: true },
    assignedInspector: { type: String, trim: true, default: '' },

    status: {
      type: String,
      enum: STATUS_VALUES,
      default: 'Scheduled',
    },

    notes: { type: String, trim: true, default: '' },

    // Soft delete, per assignment guide (delete can be optional/soft).
    isDeleted: { type: Boolean, default: false },
  },
  { timestamps: true }
);

scheduleSchema.index({ scheduledDate: 1 });
scheduleSchema.index({ status: 1 });

const Schedule = mongoose.model('Schedule', scheduleSchema);
Schedule.STATUS_VALUES = STATUS_VALUES;

module.exports = Schedule;

