10	  {
11	    item: { type: String, required: true, trim: true },
12	    result: { type: String, enum: CHECKLIST_RESULTS, default: 'N/A' },
13	    remarks: { type: String, default: '', trim: true },
14	  },
15	  { _id: false }
16	);
17	
18	const defectSchema = new mongoose.Schema({
19	  description: { type: String, required: true, trim: true },
20	  severity: { type: String, enum: DEFECT_SEVERITIES, default: 'Minor' },
21	  photoUrl: { type: String, default: '' },
22	  status: { type: String, enum: DEFECT_STATUSES, default: 'Open' },
23	  raisedDate: { type: Date, default: Date.now },
24	});
25	
26	const inspectionSchema = new mongoose.Schema(
27	  {
28	    // Assigned by the controller (see nextReportNo in inspectionController.js) from the
29	    // current max in the collection, not an ever-incrementing counter — so deleting the
30	    // highest-numbered report and creating a new one reissues that same number instead of
31	    // skipping ahead. unique (not sparse) so two reports can never collide on the same number.
32	    reportNo: { type: String, required: true, unique: true, trim: true },
33	
34	    // The lift this report is about, plus the optional scheduled visit it followed up on
35	    // (Lift -> Schedule -> Inspection, per the client's workflow doc). liftId is the source
36	    // of truth; liftCode/block below are a snapshot taken at creation time (see controller),
37	    // not live-joined - an inspection report is a historical record, so it shouldn't silently
