1	import { useState } from 'react';
2	import { useFormik } from 'formik';
3	import * as Yup from 'yup';
4	import {
5	  Box,
6	  Button,
7	  Dialog,
8	  DialogActions,
9	  DialogContent,
10	  DialogTitle,
11	  Grid,
12	  IconButton,
13	  MenuItem,
14	  Stack,
15	  TextField,
16	  Typography,
17	} from '@mui/material';
18	import DeleteIcon from '@mui/icons-material/DeleteOutlined';
19	import LiftSelect from '../lifts/LiftSelect';
20	import { generateDraftNotes } from '../../api/scheduleApi';
21	import { useFileUpload } from '../../hooks/useFileUpload';
22	import { SCHEDULE_STATUSES } from '../../utils/scheduleHelpers';
23	
24	const emptySchedule = {
25	  townCouncil: '',
26	  liftCompany: '',
27	  blockAddress: '',
28	  scheduledDate: '',
29	  assignedInspector: '',
30	  notes: '',
31	  status: 'Scheduled',
32	  liftId: '',
33	  attachments: [],
34	};
35	
36	// Client-side gate before we ever call the shared upload hook — the presign
37	// endpoint has no file-type/size checks of its own, so this is the only
38	// guard in place today. Limits are generous enough for a phone photo or a
39	// short voice note while keeping uploads fast on a mobile connection.
40	const MAX_ATTACHMENT_SIZE_BYTES = 5 * 1024 * 1024;
41	const ALLOWED_ATTACHMENT_TYPES = [
42	  'image/jpeg',
43	  'image/png',
44	  'image/webp',
45	  'audio/mpeg',
46	  'audio/wav',
47	  'audio/mp4',
48	  'audio/x-m4a',
49	];
50	
51	const schema = Yup.object({
52	  townCouncil: Yup.string().trim().required('Town council is required'),
53	  liftCompany: Yup.string().trim().required('Lift company is required'),
54	  blockAddress: Yup.string().trim().required('Block/Lift address is required'),
55	  scheduledDate: Yup.date().typeError('Enter a valid date').required('Scheduled date is required'),
56	  status: Yup.string().oneOf(SCHEDULE_STATUSES).required(),
57	  assignedInspector: Yup.string(),
58	  notes: Yup.string(),
59	});
60	
61	export default function ScheduleFormDialog({ open, schedule, onClose, onSubmit }) {
62	  const [draftLoading, setDraftLoading] = useState(false);
63	  const [localError, setLocalError] = useState(null);
64	  const { uploadFile, uploading, progress, error: uploadError } = useFileUpload();
65	
66	  const formik = useFormik({
67	    enableReinitialize: true,
68	    initialValues: schedule
69	      ? {
70	          ...emptySchedule,
71	          ...schedule,
72	          scheduledDate: schedule.scheduledDate ? schedule.scheduledDate.slice(0, 10) : '',
73	          liftId: schedule.liftId || '',
74	          attachments: schedule.attachments || [],
75	        }
76	      : emptySchedule,
77	    validationSchema: schema,
78	    onSubmit: async (values, { setSubmitting }) => {
79	      try {
80	        await onSubmit(values);
81	      } finally {
82	        setSubmitting(false);
83	      }
84	    },
85	  });
86	
87	  // Auto-fills Block/Lift Address from the Lifts module (Student 1's feature)
88	  // when a lift is picked — one click instead of retyping what's already on
89	  // record there. LiftSelect degrades to an empty picker (see LiftSelect.jsx)
90	  // if no lift directory is available yet, so manual entry always still works.
91	  function handleLiftChange(liftId, lift) {
92	    formik.setFieldValue('liftId', liftId);
93	    if (lift) {
94	      formik.setFieldValue('blockAddress', `Lift ${lift.liftCode} — Blk ${lift.block}`);
95	    }
96	  }
97	
98	  async function handleGenerateDraft() {
99	    if (!formik.values.blockAddress) {
100	      setLocalError('Fill in Block/Lift Address before generating a draft.');
101	      return;
102	    }
103	
104	    setDraftLoading(true);
105	    setLocalError(null);
106	    try {
107	      const { notes } = await generateDraftNotes({
108	        townCouncil: formik.values.townCouncil,
109	        liftCompany: formik.values.liftCompany,
110	        blockAddress: formik.values.blockAddress,
111	        assignedInspector: formik.values.assignedInspector,
112	      });
113	      formik.setFieldValue('notes', notes);
114	    } catch (err) {
115	      setLocalError(err.response?.data?.message || 'Failed to generate draft');
116	    } finally {
117	      setDraftLoading(false);
118	    }
119	  }
120	
121	  async function handleFileSelect(e) {
122	    const file = e.target.files[0];
123	    e.target.value = '';
124	    if (!file) return;
125	
126	    if (!ALLOWED_ATTACHMENT_TYPES.includes(file.type)) {
127	      setLocalError('Unsupported file type. Allowed: JPG, PNG, WebP, MP3, WAV, M4A.');
128	      return;
129	    }
130	    if (file.size > MAX_ATTACHMENT_SIZE_BYTES) {
131	      setLocalError('File is too large — 5MB max per attachment.');
132	      return;
133	    }
134	
135	    setLocalError(null);
136	    try {
137	      const url = await uploadFile(file);
138	      formik.setFieldValue('attachments', [
139	        ...formik.values.attachments,
140	        { url, fileName: file.name, fileType: file.type },
141	      ]);
142	    } catch (err) {
143	      setLocalError(err.message);
144	    }
145	  }
146	
147	  function handleRemoveAttachment(index) {
148	    formik.setFieldValue(
149	      'attachments',
150	      formik.values.attachments.filter((_, i) => i !== index)
151	    );
152	  }
153	
154	  return (
155	    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
156	      <form onSubmit={formik.handleSubmit}>
157	        <DialogTitle>{schedule ? 'Edit Schedule' : 'New Spot-Check Schedule'}</DialogTitle>
158	        <DialogContent dividers>
159	          {(localError || uploadError) && (
160	            <Typography color="error" variant="body2" sx={{ mb: 1.5 }}>
161	              {localError || uploadError}
162	            </Typography>
163	          )}
164	
165	          <Box sx={{ mb: 2 }}>
166	            <LiftSelect
167	              value={formik.values.liftId}
168	              onChange={handleLiftChange}
169	              label="Link to a Lift (optional)"
170	              helperText="Auto-fills Block/Lift Address from the Lifts directory"
171	            />
172	          </Box>
173	
174	          <Grid container spacing={2}>
175	            <Grid size={6}>
176	              <TextField
177	                name="townCouncil"
178	                label="Town Council"
179	                fullWidth
180	                value={formik.values.townCouncil}
181	                onChange={formik.handleChange}
182	                error={formik.touched.townCouncil && Boolean(formik.errors.townCouncil)}
183	                helperText={formik.touched.townCouncil && formik.errors.townCouncil}
184	              />
185	            </Grid>
186	            <Grid size={6}>
187	              <TextField
188	                name="liftCompany"
189	                label="Lift Company"
190	                fullWidth
191	                value={formik.values.liftCompany}
192	                onChange={formik.handleChange}
193	                error={formik.touched.liftCompany && Boolean(formik.errors.liftCompany)}
194	                helperText={formik.touched.liftCompany && formik.errors.liftCompany}
195	              />
196	            </Grid>
197	            <Grid size={12}>
198	              <TextField
199	                name="blockAddress"
200	                label="Block / Lift Address"
201	                fullWidth
202	                value={formik.values.blockAddress}
203	                onChange={formik.handleChange}
204	                error={formik.touched.blockAddress && Boolean(formik.errors.blockAddress)}
205	                helperText={formik.touched.blockAddress && formik.errors.blockAddress}
206	              />
207	            </Grid>
208	            <Grid size={6}>
209	              <TextField
210	                name="scheduledDate"
211	                label="Scheduled Date"
212	                type="date"
213	                fullWidth
214	                slotProps={{ inputLabel: { shrink: true } }}
215	                value={formik.values.scheduledDate}
216	                onChange={formik.handleChange}
217	                error={formik.touched.scheduledDate && Boolean(formik.errors.scheduledDate)}
218	                helperText={formik.touched.scheduledDate && formik.errors.scheduledDate}
219	              />
220	            </Grid>
221	            <Grid size={6}>
222	              <TextField
223	                select
224	                name="status"
225	                label="Status"
226	                fullWidth
227	                value={formik.values.status}
228	                onChange={formik.handleChange}
229	              >
230	                {SCHEDULE_STATUSES.map((status) => (
231	                  <MenuItem key={status} value={status}>
232	                    {status}
233	                  </MenuItem>
234	                ))}
235	              </TextField>
236	            </Grid>
237	            <Grid size={12}>
238	              <TextField
239	                name="assignedInspector"
240	                label="Assigned Inspector"
241	                fullWidth
242	                value={formik.values.assignedInspector}
243	                onChange={formik.handleChange}
244	              />
245	            </Grid>
246	
247	            <Grid size={12}>
248	              <Stack direction="row" justifyContent="space-between" alignItems="center" mb={0.5}>
249	                <Typography variant="body2">Notes</Typography>
250	                <Button size="small" onClick={handleGenerateDraft} disabled={draftLoading}>
251	                  {draftLoading ? 'Generating…' : 'Generate Draft from AI'}
252	                </Button>
253	              </Stack>
254	              <TextField
255	                name="notes"
256	                fullWidth
257	                multiline
258	                rows={2}
259	                value={formik.values.notes}
260	                onChange={formik.handleChange}
261	              />
262	            </Grid>
263	
264	            <Grid size={12}>
265	              <Typography variant="body2" sx={{ mb: 0.5 }}>
266	                Attachments (photos / audio field notes)
267	              </Typography>
268	              <Button component="label" variant="outlined" size="small" disabled={uploading}>
269	                {uploading ? `Uploading… ${progress}%` : 'Add Attachment'}
270	                <input
271	                  type="file"
272	                  hidden
273	                  accept="image/jpeg,image/png,image/webp,audio/*"
274	                  onChange={handleFileSelect}
275	                />
276	              </Button>
277	              {formik.values.attachments.length > 0 && (
278	                <Stack spacing={0.5} sx={{ mt: 1 }}>
279	                  {formik.values.attachments.map((attachment, index) => (
280	                    <Stack key={attachment.url} direction="row" alignItems="center" spacing={1}>
281	                      <Typography
282	                        variant="body2"
283	                        component="a"
284	                        href={attachment.url}
285	                        target="_blank"
286	                        rel="noreferrer"
287	                        sx={{ flexGrow: 1 }}
288	                      >
289	                        {attachment.fileName || attachment.url}
290	                      </Typography>
291	                      <IconButton size="small" onClick={() => handleRemoveAttachment(index)}>
292	                        <DeleteIcon fontSize="small" />
293	                      </IconButton>
294	                    </Stack>
295	                  ))}
296	                </Stack>
