1	import { useRef, useState } from 'react';
2	import { useFormik } from 'formik';
3	import * as Yup from 'yup';
4	import { useSnackbar } from 'notistack';
5	import {
6	  Box,
7	  Button,
8	  Dialog,
9	  DialogActions,
10	  DialogContent,
11	  DialogTitle,
12	  Divider,
13	  Grid,
14	  TextField,
15	  Typography,
16	} from '@mui/material';
17	import DefectSelect from './DefectSelect';
18	import PhotoUploader from './PhotoUploader';
19	import SignaturePad from './SignaturePad';
20	import { useFileUpload } from '../../hooks/useFileUpload';
21	import { dateInputValue } from '../../utils/formatDate';
22	
23	function SectionLabel({ children }) {
24	  return (
25	    <Typography
26	      variant="caption"
27	      sx={{ fontWeight: 600, letterSpacing: 0.4, color: 'text.secondary', textTransform: 'uppercase' }}
28	    >
29	      {children}
30	    </Typography>
31	  );
32	}
33	
34	const emptyRectification = {
35	  defectId: '',
36	  rectifiedBy: '',
37	  liftCompanyName: '',
38	  dateRectified: '',
39	  proofPhotos: [],
40	  signatureUrl: '',
41	  remarks: '',
42	};
43	
44	const schema = Yup.object({
45	  defectId: Yup.string().required('Defect is required'),
46	  rectifiedBy: Yup.string().trim().required('Rectified By is required'),
47	  liftCompanyName: Yup.string(),
48	  dateRectified: Yup.string().required('Date Rectified is required'),
49	  remarks: Yup.string(),
50	});
51	
52	/**
53	 * Create/edit dialog for a rectification record. Unlike DefectFormDialog (one Save
54	 * button), this form has two distinct actions - "Save as Draft" and "Submit" - each with
55	 * different validation, since Submit additionally requires a photo + signature. Both
56	 * route through the same Formik onSubmit; which one fires is captured in
57	 * targetStatusRef right before triggering formik.handleSubmit(), so the base-field
58	 * validation (defectId/rectifiedBy/dateRectified) stays centralised either way.
59	 */
60	export default function RectificationForm({ open, rectification, onClose, onSubmit }) {
61	  const { enqueueSnackbar } = useSnackbar();
62	  const isEdit = Boolean(rectification);
63	  const isEndorsed = isEdit && rectification.status === 'Endorsed';
64	  const isSubmittedAlready = isEdit && rectification.status === 'Submitted';
65	
66	  // Files (photos/signature) are only locked once the record is finalized by an EM
67	  // staff endorsement - a Submitted record can still be amended before that happens.
68	  const filesDisabled = isEndorsed;
69	
70	  const targetStatusRef = useRef(null);
71	  const signaturePadRef = useRef(null);
72	  const [showPad, setShowPad] = useState(!rectification?.signatureUrl);
73	  const [signatureDrawn, setSignatureDrawn] = useState(false);
74	  const signatureUpload = useFileUpload();
75	
76	  const formik = useFormik({
77	    enableReinitialize: true,
78	    initialValues: rectification
79	      ? {
80	          ...emptyRectification,
81	          ...rectification,
82	          defectId: rectification.defectId?._id || rectification.defectId || '',
83	          dateRectified: dateInputValue(rectification.dateRectified),
84	        }
85	      : emptyRectification,
86	    validationSchema: schema,
87	    onSubmit: async (values, { setSubmitting }) => {
88	      try {
89	        await performSubmit(values, targetStatusRef.current);
90	      } finally {
91	        setSubmitting(false);
92	      }
93	    },
94	  });
95	
96	  async function performSubmit(values, targetStatus) {
97	    let signatureUrl = values.signatureUrl;
98	
99	    if (showPad && !filesDisabled) {
100	      if (!signaturePadRef.current || signaturePadRef.current.isEmpty()) {
101	        if (targetStatus === 'Submitted') {
102	          enqueueSnackbar('Draw a signature before submitting', { variant: 'warning' });
103	          return;
104	        }
105	      } else {
106	        try {
107	          const blob = await signaturePadRef.current.toBlob();
108	          const file = new File([blob], `signature-${rectification?._id || 'new'}.png`, { type: 'image/png' });
109	          signatureUrl = await signatureUpload.uploadFile(file, 'rectifications');
110	        } catch (err) {
111	          enqueueSnackbar(`Failed to upload signature: ${err.message}`, { variant: 'error' });
112	          return;
113	        }
114	      }
115	    }
116	
117	    if (targetStatus === 'Submitted' && (!values.proofPhotos.length || !signatureUrl)) {
118	      enqueueSnackbar('Add at least 1 proof photo and a signature before submitting', { variant: 'warning' });
119	      return;
120	    }
121	
122	    const payload = { ...values, signatureUrl };
123	    if (targetStatus) payload.status = targetStatus;
124	
125	    try {
126	      await onSubmit(payload);
127	    } catch (err) {
128	      enqueueSnackbar(err.response?.data?.message || 'Failed to save rectification', { variant: 'error' });
129	    }
130	  }
131	
132	  function fireSubmit(targetStatus) {
133	    targetStatusRef.current = targetStatus;
134	    formik.handleSubmit();
135	  }
136	
137	  const canSubmit =
138	    formik.values.proofPhotos.length > 0 && (Boolean(formik.values.signatureUrl) || signatureDrawn);
139	
140	  return (
141	    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
142	      <form onSubmit={(e) => e.preventDefault()}>
143	        <DialogTitle>{isEdit ? `Edit Rectification` : 'New Rectification'}</DialogTitle>
144	        <DialogContent dividers>
145	          <SectionLabel>What Was Fixed</SectionLabel>
146	          <Grid container spacing={2} sx={{ mt: 1, mb: 2.5 }}>
147	            <Grid size={12}>
148	              <DefectSelect
149	                value={formik.values.defectId}
150	                onChange={(id) => formik.setFieldValue('defectId', id)}
151	                error={formik.touched.defectId && Boolean(formik.errors.defectId)}
152	                helperText={formik.touched.defectId && formik.errors.defectId}
153	                disabled={isEdit}
154	              />
155	            </Grid>
156	          </Grid>
157	
158	          <Divider />
159	
160	          <SectionLabel>Rectification Details</SectionLabel>
161	          <Grid container spacing={2} sx={{ mt: 1, mb: 2.5 }}>
162	            <Grid size={6}>
163	              <TextField
164	                name="rectifiedBy"
165	                label="Rectified By"
166	                placeholder="Technician name"
167	                fullWidth
168	                value={formik.values.rectifiedBy}
169	                onChange={formik.handleChange}
170	                error={formik.touched.rectifiedBy && Boolean(formik.errors.rectifiedBy)}
171	                helperText={formik.touched.rectifiedBy && formik.errors.rectifiedBy}
172	              />
173	            </Grid>
174	            <Grid size={6}>
175	              <TextField
176	                name="liftCompanyName"
177	                label="Lift Company"
178	                placeholder="e.g., Acme Lift Co"
179	                fullWidth
180	                value={formik.values.liftCompanyName}
181	                onChange={formik.handleChange}
182	              />
183	            </Grid>
184	            <Grid size={12}>
185	              <TextField
186	                type="date"
187	                name="dateRectified"
188	                label="Date Rectified"
189	                fullWidth
190	                InputLabelProps={{ shrink: true }}
191	                value={formik.values.dateRectified}
192	                onChange={formik.handleChange}
193	                error={formik.touched.dateRectified && Boolean(formik.errors.dateRectified)}
194	                helperText={formik.touched.dateRectified && formik.errors.dateRectified}
195	              />
196	            </Grid>
197	            <Grid size={12}>
198	              <TextField
199	                name="remarks"
200	                label="Remarks"
201	                placeholder="Any additional notes..."
202	                fullWidth
203	                multiline
204	                rows={2}
205	                value={formik.values.remarks}
206	                onChange={formik.handleChange}
207	              />
208	            </Grid>
209	          </Grid>
210	
211	          <Divider />
212	
213	          <SectionLabel>Proof of Fix</SectionLabel>
214	          <Box sx={{ mt: 1, mb: 2.5 }}>
215	            <PhotoUploader
216	              photos={formik.values.proofPhotos}
217	              onChange={(photos) => formik.setFieldValue('proofPhotos', photos)}
218	              disabled={filesDisabled}
219	              onError={(message) => enqueueSnackbar(message, { variant: 'error' })}
220	            />
221	          </Box>
222	
223	          <Divider />
224	
225	          <SectionLabel>E-Signature</SectionLabel>
226	          <Box sx={{ mt: 1 }}>
227	            {filesDisabled || (!showPad && formik.values.signatureUrl) ? (
228	              <Box>
229	                <Box
230	                  component="img"
231	                  src={formik.values.signatureUrl}
232	                  alt="Signature"
233	                  sx={{ maxWidth: 300, height: 100, border: 1, borderColor: 'divider', borderRadius: 1, bgcolor: '#fff' }}
234	                />
235	                {!filesDisabled && (
236	                  <Button
237	                    size="small"
238	                    sx={{ display: 'block', mt: 1 }}
239	                    onClick={() => {
240	                      setShowPad(true);
241	                      formik.setFieldValue('signatureUrl', '');
242	                    }}
243	                  >
244	                    Redraw Signature
245	                  </Button>
246	                )}
247	              </Box>
248	            ) : (
249	              <SignaturePad ref={signaturePadRef} disabled={filesDisabled} onChange={setSignatureDrawn} />
250	            )}
251	          </Box>
252	        </DialogContent>
253	        <DialogActions>
254	          <Button onClick={onClose} disabled={formik.isSubmitting}>
255	            Cancel
256	          </Button>
257	          {isEndorsed && (
258	            <Button variant="contained" disabled={formik.isSubmitting} onClick={() => fireSubmit(null)}>
259	              Save Changes
260	            </Button>
261	          )}
262	          {isSubmittedAlready && !isEndorsed && (
263	            <Button variant="contained" disabled={formik.isSubmitting} onClick={() => fireSubmit('Submitted')}>
264	              Save Changes
265	            </Button>
266	          )}
267	          {!isEndorsed && !isSubmittedAlready && (
268	            <>
269	              <Button variant="outlined" disabled={formik.isSubmitting} onClick={() => fireSubmit('Draft')}>
270	                Save as Draft
271	              </Button>
272	              <Button
273	                variant="contained"
274	                disabled={formik.isSubmitting || !canSubmit}
275	                onClick={() => fireSubmit('Submitted')}
276	              >
277	                Submit
278	              </Button>
279	            </>
280	          )}
281	        </DialogActions>
282	      </form>
283	    </Dialog>
284	  );
285	}
