import { useCallback, useEffect, useState } from 'react';
import * as rectificationApi from '../../api/rectificationApi';

// Wraps every /api/rectifications call (list/get one/create/update/endorse/delete) behind
// one hook, so RectificationsSection/RectificationDetail/RectificationForm all share the
// same list state instead of each re-implementing their own load()/error handling.
export function useRectifications() {
  const [rectifications, setRectifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await rectificationApi.fetchRectifications();
      setRectifications(data);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to load rectifications');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const getOne = useCallback((id) => rectificationApi.fetchRectification(id), []);

  const create = useCallback(
    async (payload) => {
      const created = await rectificationApi.createRectification(payload);
      await load();
      return created;
    },
    [load]
  );

  const update = useCallback(
    async (id, payload) => {
      const updated = await rectificationApi.updateRectification(id, payload);
      await load();
      return updated;
    },
    [load]
  );

  const endorse = useCallback(
    async (id, endorsedBy) => {
      const endorsed = await rectificationApi.endorseRectification(id, endorsedBy);
      await load();
      return endorsed;
    },
    [load]
  );

  const remove = useCallback(
    async (id) => {
      await rectificationApi.deleteRectification(id);
      await load();
    },
    [load]
  );

  return { rectifications, loading, error, reload: load, getOne, create, update, endorse, remove };
}

import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import StatusStepper from './StatusStepper';
import { downloadSchedulePdf } from './generateSchedulePdf';
import { formatDate } from '../../utils/formatDate';

// "Extending to see more details" without a page navigation, per client
// feedback — a dialog keeps the grid in place behind it, matching
// LiftDetailDialog's pattern for the Lifts feature.
export default function ScheduleDetailsModal({ open, schedule, onClose }) {
  if (!schedule) return null;

  const attachments = schedule.attachments || [];

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>{schedule.blockAddress}</DialogTitle>
      <DialogContent dividers>
        <Stack spacing={2}>
          <StatusStepper status={schedule.status} />

          <Stack spacing={0.5}>
            <Typography variant="body2">
              <strong>Town Council:</strong> {schedule.townCouncil}
            </Typography>
            <Typography variant="body2">
              <strong>Lift Company:</strong> {schedule.liftCompany}
            </Typography>
            <Typography variant="body2">
              <strong>Scheduled Date:</strong> {formatDate(schedule.scheduledDate)}
            </Typography>
            <Typography variant="body2">
              <strong>Assigned Inspector:</strong> {schedule.assignedInspector || '—'}
            </Typography>
            <Typography variant="body2">
              <strong>Notes:</strong> {schedule.notes || '—'}
            </Typography>
          </Stack>

          <Divider />

          <Typography variant="subtitle2">Attachments</Typography>
          {attachments.length === 0 && (
            <Typography variant="body2" color="text.secondary">
              No attachments.
            </Typography>
          )}
          {attachments.length > 0 && (
            <List dense disablePadding>
              {attachments.map((attachment) => (
                <ListItem key={attachment.url} disableGutters>
                  {attachment.fileType?.startsWith('image/') && (
                    <Box
                      component="img"
                      src={attachment.url}
                      alt={attachment.fileName}
                      sx={{ width: 48, height: 48, objectFit: 'cover', borderRadius: 1, mr: 1.5 }}
                    />
                  )}
                  <ListItemText
                    primary={attachment.fileName || attachment.url}
                    secondary={
                      <a href={attachment.url} target="_blank" rel="noreferrer">
                        Open
                      </a>
                    }
                  />
                </ListItem>
              ))}
            </List>
          )}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Close</Button>
        <Button variant="contained" onClick={() => downloadSchedulePdf(schedule)}>
          Generate PDF
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import { useState } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Grid,
  Stack,
  Typography,
} from '@mui/material';
import EditIcon from '@mui/icons-material/EditOutlined';
import StatusChip from '../../components/StatusChip';
import EndorseButton from './EndorseButton';
import { formatDate } from '../../utils/formatDate';
import { RECTIFICATION_STATUS_COLORS } from '../../theme/statusColors';

function Field({ label, children }) {
  return (
    <Box>
      <Typography variant="caption" color="text.secondary" display="block">
        {label}
      </Typography>
      <Typography variant="body2">{children ?? '—'}</Typography>
    </Box>
  );
}

/**
 * Read-only view of a single rectification: the defect it closes out, who fixed it,
 * the full proof-photo gallery (click any thumbnail to enlarge), the signature, remarks,
 * and - once endorsed - who signed off on it and when. Edit and Endorse actions live
 * here rather than inline in the table, since they need this much context on screen.
 */
export default function RectificationDetail({ open, rectification, onClose, onEdit, onEndorse }) {
  const [enlarged, setEnlarged] = useState(null);

  if (!rectification) return null;
  const defect = rectification.defectId || {};

  return (
    <>
      <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
        <DialogTitle>
          <Stack direction="row" spacing={1.5} alignItems="center">
            <span>Rectification Details</span>
            <StatusChip value={rectification.status} colorMap={RECTIFICATION_STATUS_COLORS} />
          </Stack>
        </DialogTitle>
        <DialogContent dividers>
          <Grid container spacing={2} sx={{ mb: 2.5 }}>
            <Grid size={12}>
              <Field label="Defect">
                {defect.defectNo ? `${defect.defectNo} — ${defect.title || defect.description || ''}` : '—'}
              </Field>
            </Grid>
            <Grid size={6}>
              <Field label="Rectified By">{rectification.rectifiedBy}</Field>
            </Grid>
            <Grid size={6}>
              <Field label="Lift Company">{rectification.liftCompanyName}</Field>
            </Grid>
            <Grid size={6}>
              <Field label="Date Rectified">{formatDate(rectification.dateRectified)}</Field>
            </Grid>
          </Grid>

          <Divider />

          <Typography
            variant="caption"
            sx={{ fontWeight: 600, letterSpacing: 0.4, color: 'text.secondary', textTransform: 'uppercase' }}
          >
            Proof Photos
          </Typography>
          <Stack direction="row" spacing={1.5} flexWrap="wrap" sx={{ mt: 1, mb: 2.5 }}>
            {rectification.proofPhotos?.length ? (
              rectification.proofPhotos.map((url, index) => (
                <Box
                  key={url + index}
                  component="img"
                  src={url}
                  alt={`Proof photo ${index + 1}`}
                  onClick={() => setEnlarged(url)}
                  sx={{
                    width: 88,
                    height: 88,
                    objectFit: 'cover',
                    borderRadius: 1,
                    border: 1,
                    borderColor: 'divider',
                    cursor: 'pointer',
                  }}
                />
              ))
            ) : (
              <Typography variant="body2" color="text.secondary">
                No proof photos yet.
              </Typography>
            )}
          </Stack>

          <Divider />

          <Typography
            variant="caption"
            sx={{ fontWeight: 600, letterSpacing: 0.4, color: 'text.secondary', textTransform: 'uppercase' }}
          >
            E-Signature
          </Typography>
          <Box sx={{ mt: 1, mb: 2.5 }}>
            {rectification.signatureUrl ? (
              <Box
                component="img"
                src={rectification.signatureUrl}
                alt="Signature"
                onClick={() => setEnlarged(rectification.signatureUrl)}
                sx={{
                  maxWidth: 260,
                  height: 90,
                  border: 1,
                  borderColor: 'divider',
                  borderRadius: 1,
                  bgcolor: '#fff',
                  cursor: 'pointer',
                }}
              />
            ) : (
              <Typography variant="body2" color="text.secondary">
                Not signed yet.
              </Typography>
            )}
          </Box>

          <Divider />

          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid size={12}>
              <Field label="Remarks">{rectification.remarks}</Field>
            </Grid>
            {rectification.status === 'Endorsed' && (
              <>
                <Grid size={6}>
                  <Field label="Endorsed By">{rectification.endorsedBy}</Field>
                </Grid>
                <Grid size={6}>
                  <Field label="Endorsed Date">{formatDate(rectification.endorsedDate)}</Field>
                </Grid>
              </>
            )}
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Close</Button>
          {rectification.status !== 'Endorsed' && (
            <Button startIcon={<EditIcon />} onClick={onEdit}>
              Edit
            </Button>
          )}
          <EndorseButton rectification={rectification} onEndorse={onEndorse} />
        </DialogActions>
      </Dialog>

      {/* Lightbox: click a thumbnail (or the signature) to see it full-size. */}
      <Dialog open={Boolean(enlarged)} onClose={() => setEnlarged(null)} maxWidth="md">
        <Box
          component="img"
          src={enlarged}
          alt="Enlarged"
          sx={{ maxWidth: '100%', maxHeight: '80vh', display: 'block', bgcolor: '#fff' }}
        />
      </Dialog>
    </>
  );
}

// Maps each module's status enum to a MUI Chip color, consumed by <StatusChip>.

export const LIFT_STATUS_COLORS = {
  Active: 'success',
  Maintenance: 'warning',
  'Out of Service': 'error',
  Decommissioned: 'default',
};

// Scheduling is now live (backend/src/models/scheduling/Schedule.js) — this
// matches its real STATUS_VALUES enum exactly.
export const SCHEDULE_STATUS_COLORS = {
  Scheduled: 'default',
  Assigned: 'info',
  'In Progress': 'warning',
  Completed: 'success',
  Cancelled: 'default',
};

// Inspections module has landed (backend/src/models/inspections/Inspection.js) - matches
// its real overallStatus enum. `compliance` (Pass / Defect Found) uses its own inline
// colours in Inspections.jsx rather than this map, since it's a separate field.
export const INSPECTION_STATUS_COLORS = {
  Draft: 'default',
  Submitted: 'info',
  'Under Review': 'warning',
  Closed: 'success',
};

export const DEFECT_SEVERITY_COLORS = {
  Minor: 'warning',
  Major: 'warning',
  Critical: 'error',
};

export const DEFECT_COMPLIANCE_COLORS = {
  Pass: 'success',
  'Defect Found': 'error',
};

// Defects module has landed (backend/src/models/defects/Defect.js) - matches its real
// status enum exactly.
export const DEFECT_STATUS_COLORS = {
  Open: 'error',
  'In Progress': 'warning',
  Resolved: 'success',
  Closed: 'default',
};

// Rectifications module has landed (backend/src/models/rectifications/Rectification.js) -
// matches its real status enum exactly (previously Pending/Completed, a placeholder from
// before the module existed).
export const RECTIFICATION_STATUS_COLORS = {
  Draft: 'default',
  Submitted: 'info',
  Endorsed: 'success',
};

