          <Typography variant="h6" color="text.secondary">
            {tab ? tab.label : 'Select a tab to get started'}
          </Typography>
          {tab && <Typography variant="body2">Module coming soon.</Typography>}
        </Stack>
      )}
    </Box>
  );
}

